widget.solution:
def quotient_table(n, d):
    """Addition table of Z_n / <d>, cosets named by least element."""
    if n % d != 0:
        raise ValueError(f"{d} does not divide {n}")
    # a + <d> has least element a mod d, so the cosets add mod d
    return [[(a + b) % d for b in range(d)] for a in range(d)]
